import { I, dish } from "./catalog-kit.ts";
import type { Recipe, RecipeSource } from "./types";

const packSource: RecipeSource = {
  book: "Betty Crocker\'s International Cookbook",
  author: "Betty Crocker / General Mills",
  year: 1980,
  era: "1980s",
  archiveId: "betty-crockers-international-cookbook",
  credit: "Betty Crocker\'s International Cookbook. Internet Archive betty-crockers-international-cookbook. Founder-cleared free use.",
};

function h(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  nutrition: Recipe["nutrition"],
): Recipe {
  return dish({
    id, name, cuisine, description, minutes, protein, plate,
    tags: Array.from(new Set(["vintage", "book-betty-intl", "era-1980s", ...tags])),
    ingredients, steps, nutrition, source: packSource,
  });
}

