export const BETTY_INTL_RECIPES: Recipe[] = [
  h('bint-001', 'Alpine Cheese Supper', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'The word raclette comes from the French racler, meaning to scrape.', [I('new potatoes (12 to 14)', 2, 'lb', 'Produce'), I('imported Swiss raclette cheese', 1, 'lb', 'Dairy & Eggs'), I('Freshly ground pepper', 1, '', 'Herbs & Spices'), I('jar (8 ounces) midget dill pickles or gherkins', 1, '', 'Pantry'), I('jar (8 ounces) pickled cocktail onions', 1, '', 'Pantry'), I('water', 1, '', 'Other'), I('salt', 1, '', 'Herbs & Spices')], ['Heat 1 inch salted water (1 teaspoon salt to 1 cup water) to boiling.', 'Add potatoes.', 'Heat to boiling; reduce heat.', 'Cover and cook until tender, 20 to 25 minutes; drain.', 'Keep warm.', 'Cut cheese into 4 pieces; divide among 4 individual ovenproof casseroles.', 'Heat in 400° oven until cheese is melted, about 10 minutes.', 'Place each hot casserole on a dinner plate.', 'Guests sprinkle potatoes with pepper, then swirl in melted cheese.', 'Potatoes are eaten alternately with pickles and onions.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-002', 'Beef-Cabbage Loaf', 'American', ["section-book-betty-intl"], 'beef', 'bowl', 45, 'Try this quick Finnish casserole when time is limited.', [I('medium head cabbage, coarsely shredded (8 cups)', 1, '', 'Produce'), I('water', 0.25, 'cups', 'Other'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('ground beef', 1, 'lb', 'Meat & Seafood'), I('soft bread crumbs (about 1 1/2 slices)', 1, 'cups', 'Bakery'), I('milk', 0.5, 'cups', 'Dairy & Eggs'), I('small onion, chopped', 1, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('dried marjoram leaves', 0.25, 'tsp', 'Herbs & Spices'), I('cranberry sauce (if desired)', 1, '', 'Pantry'), I('creamed potatoes (if desired)', 1, '', 'Produce')], ['Heat cabbage, water and 1/4 teaspoon salt to boiling; reduce heat.', 'Cover and simmer until cabbage is wilted, about 5 minutes; drain.', 'Mix remaining ingredients.', 'Place half the cabbage in ungreased 2-quart casserole.', 'Spread beef mixture over cabbage; top with remaining cabbage.', 'Cover and cook in 350° oven until done, 55 to 60 minutes.', 'Serve with cranberry sauce and creamed potatoes if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-003', 'Bok Choy with Bean Curd', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'This unusual side dish from China serves as a good protein supplement to meatless main dishes as well as a conversation piece.', [I('bean curd', 1, 'lb', 'Pantry'), I('medium stalks bok choy', 4, '', 'Produce'), I('green onions (with tops)', 4, '', 'Produce'), I('vegetable oil', 0.25, 'cups', 'Pantry'), I('can (4 ounces) button mushrooms, drained (reserve liquid)', 1, '', 'Pantry'), I('oyster sauce', 3, 'tbsp', 'Pantry'), I('instant chicken bouillon', 0.5, 'tsp', 'Pantry'), I('cornstarch', 1, 'tbsp', 'Pantry'), I('cold water', 1, 'tbsp', 'Other')], ['Cut bean curd into 3/4-inch cubes; drain thoroughly.', 'Cut bok choy (with leaves) diagonally into 1/4-inch slices.', 'Cut green onions into 2-inch pieces.', 'Heat 2 tablespoons of the oil in wok or 10-inch skillet over medium-high heat until hot.', 'Cook bean curd, stirring carefully, 3 to 5 minutes.', 'Remove bean curd.', 'Add remaining oil and the bok choy to wok; stir-fry over medium-high heat 2 minutes.', 'Add mushrooms.', 'Add enough water to reserved liquid to measure 1/2 cup.', 'Stir reserved liquid, the oyster sauce and bouillon into vegetables; heat to boiling.', 'Mix cornstarch and water; stir into vegetable mixture.', 'Cook and stir until thickened, about 1 minute.', 'Stir in bean curd and green onions; heat until hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-004', 'Cauliflower Soup', 'American', ["section-book-betty-intl"], 'veg', 'soup', 45, 'Popular throughout Scandinavia, Cauliflower Soup can be served hot or cold.', [I('water', 2, 'cups', 'Other'), I('medium head cauliflower (1 to 1 1/2 pounds), separated into flowerets', 1, '', 'Produce'), I('medium onion, sliced', 1, '', 'Produce'), I('margarine or butter', 2, 'tbsp', 'Dairy & Eggs'), I('flour', 2, 'tbsp', 'Pantry'), I('water', 1, 'cups', 'Other'), I('instant chicken bouillon', 1, 'tbsp', 'Pantry'), I('celery salt', 0.5, 'tsp', 'Herbs & Spices'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices'), I('half-and-half', 1, 'cups', 'Dairy & Eggs'), I('Ground nutmeg', 1, '', 'Herbs & Spices')], ['Heat 2 cups water to boiling in 3-quart saucepan; add cauliflower and onion.', 'Heat to boiling; reduce heat.', 'Cover and simmer until tender, about 10 minutes; do not drain.', 'Pour cauliflower and onion with water into blender container.', 'Cover and blend on high speed until smooth.', 'Heat margarine in 3-quart saucepan until melted; stir in flour.', 'Cook, stirring constantly, until mixture is smooth and bubbly; remove from heat.', 'Stir in 1 cup water.', 'Heat to boiling, stirring constantly; boil and stir 1 minute.', 'Stir in cauliflower mixture, bouillon, celery salt, salt and pepper; heat just to boiling.', 'Stir in half-and-half; heat just until hot.', 'Sprinkle each serving with nutmeg.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-005', 'Cheese Puffs', 'American', ["section-book-betty-intl"], 'eggs', 'dessert', 45, 'Filo (or phyllo) leaves, also called strudel leaves, are paper-thin pastry sheets used throughout the Middle East in many dishes, including Baklava (page 317).', [I('feta cheese', 1, 'lb', 'Dairy & Eggs'), I('eggs, slightly beaten', 2, '', 'Dairy & Eggs'), I('finely chopped chives', 0.25, 'cups', 'Produce'), I('white pepper', 0.25, 'tsp', 'Herbs & Spices'), I('frozen filo leaves, thawed', 1, 'lb', 'Frozen'), I('margarine or butter, melted', 0.25, 'cups', 'Dairy & Eggs')], ['Crumble cheese in small bowl; mash with fork.', 'Stir in eggs, chives and white pepper until well mixed.', 'Cut filo leaves lengthwise into 3 strips.', 'Cover with waxed paper, then with damp towel to prevent drying.', 'Use 2 layers filo leaves for each strip.', 'Place 1 heaping teaspoon filling on end of strip; fold end over-end, in triangular shape, to opposite end. (See diagrams.)', 'Place on greased cookie sheet.', 'Repeat with remaining filling. (Puffs can be covered and refrigerated no longer than 24 hours at this point.)', 'Heat oven to 350°.', 'Brush puffs with margarine.', 'Bake until puffed and golden, about 20 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-006', 'Chili-Cheese Foldovers', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'Quesadillas are fine fare for a light Mexican-style lunch or supper, but may be a trifle fiery for some tastes.', [I('six-inch flour tortillas', 8, '', 'Bakery'), I('shredded Cheddar cheese (4 ounces)', 1, 'cups', 'Dairy & Eggs'), I('shredded Monterey Jack cheese (4 ounces)', 1, 'cups', 'Dairy & Eggs'), I('cilantro leaves', 8, '', 'Produce'), I('medium tomato, chopped', 1, '', 'Produce'), I('chopped green onion', 0.25, 'cups', 'Produce'), I('1/4 to 1/3 cup chopped green chilies', 1, '', 'Pantry'), I('Dash of salt', 1, '', 'Herbs & Spices'), I('Red or green taco sauce (optional)', 1, '', 'Pantry'), I('Lard or shortening', 1, '', 'Pantry'), I('water', 1, '', 'Other')], ['Heat tortillas, one at a time, in ungreased hot skillet until softened, about 30 seconds. (Cover hot tortillas to prevent drying.)', 'Sprinkle 2 tablespoons each Cheddar and Monterey Jack cheese over half of each tortilla.', 'Top each with a cilantro leaf; sprinkle with tomato, green onion, chilies and salt and top with 1/2 to 1 teaspoon taco sauce.', 'Moisten edge of each tortilla with water; fold tortilla over filling.', 'Pinch to seal; secure with wooden picks. (Keep covered.)', 'Heat lard (1/4 inch) until hot.', 'Fry tortillas until golden brown, about 4 minutes.', 'Drain on paper towels.', 'Remove wooden picks.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-007', 'Chinese Barbecued Ribs', 'American', ["section-book-betty-intl"], 'pork', 'dessert', 45, 'For ease in eating, provide an ample supply of paper napkins and bowls for depositing bones.', [I('1 1/2 to 2 pounds fresh pork spareribs', 1, '', 'Meat & Seafood'), I('soy sauce', 0.25, 'cups', 'Pantry'), I('hoisin sauce or chili sauce', 0.25, 'cups', 'Pantry'), I('honey', 2, 'tbsp', 'Pantry'), I('sake or dry sherry', 2, 'tbsp', 'Pantry'), I('small clove garlic, crushed', 1, '', 'Produce')], ['Have spareribs cut crosswise into 1 1/2-inch pieces.', 'Place ribs in shallow glass or plastic dish.', 'Mix remaining ingredients; spoon over ribs.', 'Cover and refrigerate at least 2 hours.', 'Remove ribs from marinade, reserving marinade.', 'Arrange ribs meaty sides up in single layer on rack in foil-lined broiler pan.', 'Brush with reserved marinade.', 'Cover and cook in 325° oven 1 hour.', 'Brush ribs with marinade.', 'Cook uncovered, brushing occasionally with marinade, until done, about 45 minutes.', 'Brush with marinade.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-008', 'Country Terrine', 'American', ["section-book-betty-intl"], 'turkey', 'bowl', 45, 'The introduction of turkey breast keeps cost down in our version of a traditional French country paté.', [I('frozen turkey breast (6 pounds), thawed', 1, '', 'Frozen'), I('dry white wine', 0.5, 'cups', 'Pantry'), I('monosodium glutamate (optional)', 2, 'tsp', 'Pantry'), I('salt', 2, 'tsp', 'Herbs & Spices'), I('ground cloves', 0.5, 'tsp', 'Herbs & Spices'), I('ground nutmeg', 0.5, 'tsp', 'Herbs & Spices'), I('ground allspice', 0.5, 'tsp', 'Herbs & Spices'), I('pork boneless loin or leg', 1, 'lb', 'Meat & Seafood'), I('fully cooked smoked ham', 1, 'lb', 'Meat & Seafood'), I('sliced bacon or side pork', 1.5, 'lb', 'Meat & Seafood'), I('chicken livers', 0.5, 'lb', 'Meat & Seafood'), I('eggs', 6, '', 'Dairy & Eggs'), I('salt', 1, 'tbsp', 'Herbs & Spices'), I('Wine Aspic', 1, '', 'Other'), I('envelope unflavored gelatin', 1, '', 'Pantry'), I('cold water', 2, 'tbsp', 'Other'), I('instant beef bouillon', 2, 'tsp', 'Pantry'), I('dry white or red wine', 1, 'cups', 'Pantry'), I('water', 1, 'cups', 'Other')], ['Remove bones and skin from turkey breast, leaving skin intact.', 'Cut 1/4 of the turkey breast into thin slices; cut slices into 1/4-inch strips.', 'Place in shallow glass or plastic dish.', 'Mix wine, monosodium glutamate, 2 teaspoons salt, the cloves, nutmeg and allspice; pour over turkey strips.', 'Cover and refrigerate 1 hour.', 'Grind remaining turkey, the pork, ham and 1 pound of the bacon.', 'Place chicken livers, eggs and 1 tablespoon salt in blender container.', 'Cover and blend on high speed until smooth; stir into ground meats.', 'Drain turkey strips, reserving marinade.', 'Stir marinade into ground meat mixture.', 'Line 2 loaf pans, 9 x 5 x 3 inches, with aluminum foil, leaving about 3 inches overhanging sides.', 'Line pans with turkey skin if desired.', 'Place remaining bacon slices across bottoms and up sides of pans, letting slices overhang edges of pans.', 'Pack 1/4 of the ground meat mixture (about 3 1/2 cups) in each pan. (See diagram.)', 'Place half the turkey strips on mixture in each pan.', 'Cover each with half the remaining ground meat mixture; fold bacon over top. (See diagram.)', 'Place loaf pans in large shallow pan; pour very hot water (1 to 2 inches) into pan.', 'Cook uncovered in 425° oven 2 hours.', 'Remove pans from hot water; fold foil over top.', 'Place weights on terrine. (See diagram.)', 'Press down firmly 2 minutes.', 'Leave weights on pans; refrigerate loaves in pans. (Do not remove weights until terrine is completely cool.)', 'Prepare Wine Aspic.', 'Remove terrine from pans by grasping ends of aluminum foil; remove foil.', 'Place terrine on platter; cut into thin slices.', 'Cut slices into halves if desired.', 'Cut aspic into tiny squares; place around terrine.', 'Wine Aspic: Sprinkle gelatin over 2 tablespoons cold water in saucepan; stir in bouillon and wine.', 'Cook over medium heat, stirring constantly, until gelatin is dissolved.', 'Remove from heat.', 'Stir in 1 cup water.', 'Place pan with wine mixture in bowl of ice and water; stir until mixture begins to thicken, 5 to 10 minutes.', 'Pour into jelly roll pan, 15 1/2 x 10 1/2 x 1 inch.', 'Cover and refrigerate until set.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-009', 'Cucumbers and Shrimp', 'American', ["section-book-betty-intl"], 'seafood', 'green', 45, 'Add interest to this Japanese appetizer: Partially pare the cucumber in alternate lengthwise strips before slicing, leaving portions of bright green peel.', [I('can (4 1/2 ounces) shrimp, drained', 1, '', 'Pantry'), I('medium cucumbers, thinly sliced', 2, '', 'Produce'), I('vinegar', 0.25, 'cups', 'Pantry'), I('sugar', 1, 'tbsp', 'Pantry'), I('soy sauce', 1, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('Lettuce leaves', 1, '', 'Produce'), I('toasted sesame seed (see Note)', 1, 'tbsp', 'Pantry')], ['Place shrimp and cucumbers in 1 1/2-quart glass bowl.', 'Mix vinegar, sugar, soy sauce and salt; pour over shrimp and cucumbers.', 'Toss.', 'Cover and refrigerate at least 1 hour.', 'Remove salad to lettuce-lined salad bowls with slotted spoon.', 'Sprinkle with sesame seed.', 'Note: To toast, heat sesame seed in ungreased skillet over medium heat, stirring occasionally, until golden, about 2 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-010', 'Deep-Fried Mushrooms', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'A crisp complement to a dinner party menu, these tasty tidbits from Germany and Austria can also be served as tempting hot appetizers at walkabout parties.', [I('medium mushrooms', 1, 'lb', 'Produce'), I('Vegetable oil', 1, '', 'Pantry'), I('all-purpose flour', 0.5, 'cups', 'Pantry'), I('milk', 0.3333333333333333, 'cups', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('baking powder', 1, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices')], ['Trim stem ends of mushrooms 1/4 inch below caps.', 'If mushrooms are large, cut into halves.', 'Heat oil (1 inch) to 360°.', 'Beat remaining ingredients with hand beater until smooth. (Add 1 to 3 tablespoons milk if necessary.)', 'Dip mushrooms into batter, letting excess batter drip into bowl.', 'Fry mushrooms, a few at a time, until golden brown, turning once, about 2 minutes.', 'Drain on paper towels.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-011', 'Deviled Short Ribs', 'American', ["section-book-betty-intl"], 'beef', 'bowl', 45, 'Slow cooking sends pleasant aromas through the home and sharpens the appetite for these succulent deviled ribs from Britain.', [I('vegetable oil', 2, 'tbsp', 'Pantry'), I('beef short ribs', 4, 'lb', 'Meat & Seafood'), I('medium onions, sliced', 2, '', 'Produce'), I('dry mustard', 1, 'tbsp', 'Herbs & Spices'), I('Worcestershire sauce', 1, 'tbsp', 'Pantry'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('curry powder', 1, 'tsp', 'Herbs & Spices'), I('ground red pepper', 0.25, 'tsp', 'Herbs & Spices'), I('water', 0.75, 'cups', 'Other')], ['Heat oil in Dutch oven until hot.', 'Cook beef over medium heat until brown on all sides; drain.', 'Add onions.', 'Mix remaining ingredients except water; stir in water.', 'Pour over beef.', 'Cover and cook in 350° oven until tender, about 2 hours.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-012', 'Egg Rolls', 'American', ["section-book-betty-intl"], 'pork', 'skillet', 45, 'Traditional egg roll skins can be purchased at many American supermarkets; but for more delicate, light-as-a-feather egg rolls, look for spring roll skins, sometimes called Shanghai spring roll skins.', [I('ground pork', 1, 'lb', 'Meat & Seafood'), I('finely shredded cabbage', 3, 'cups', 'Produce'), I('can (8 1/2 ounces) bamboo shoots, drained and chopped', 1, '', 'Pantry'), I('chopped mushrooms', 0.5, 'cups', 'Produce'), I('medium green onions, sliced', 4, '', 'Produce'), I('soy sauce', 2, 'tbsp', 'Pantry'), I('cornstarch', 1, 'tsp', 'Pantry'), I('five spice powder', 1, 'tsp', 'Pantry'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('sugar', 0.5, 'tsp', 'Pantry'), I('egg roll skins (16 to 18)', 1, 'lb', 'Produce'), I('Vegetable oil', 1, '', 'Pantry'), I('Sweet-and-Sour Sauce and Hot Mustard Sauce', 1, '', 'Other'), I('plum or grape jelly', 0.25, 'cups', 'Pantry'), I('chili sauce', 0.25, 'cups', 'Pantry'), I('dry mustard', 3, 'tbsp', 'Herbs & Spices'), I('water', 2, 'tbsp', 'Other'), I('soy sauce', 1, 'tbsp', 'Pantry')], ['Stir-fry pork in wok or 10-inch skillet until brown.', 'Remove pork from wok; drain, reserving 2 tablespoons fat.', 'Stir-fry cabbage, bamboo shoots, mushrooms and onions in reserved fat.', 'Mix soy sauce, cornstarch, five spice powder, salt and sugar; pour over vegetable mixture.', 'Stir-fry 1 minute; cool.', 'Mix pork and vegetables.', 'Cover egg roll skins with damp towel to prevent drying.', 'Place 1/4 cup pork mixture on center of each egg roll skin.', 'Fold one corner of egg roll skin over filling; overlap the two opposite corners. (See diagram.)', 'Moisten fourth corner with water; fold over to make into roll. (See diagram.)', 'Heat oil (1 1/2 to 1 3/4 inches) to 360°.', 'Fry 3 to 5 egg rolls at a time until golden brown, turning once, about 3 minutes.', 'Drain on paper towels.', 'Serve hot with Sweet-and-Sour Sauce and Hot Mustard Sauce.', 'Sweet-and-Sour Sauce: Heat 1/4 cup plum or grape jelly and 1/4 cup chili sauce in small saucepan, stirring constantly, until jelly is melted.', 'Hot Mustard Sauce: Mix 3 tablespoons dry mustard, 2 tablespoons water and 1 tablespoon soy sauce until smooth.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-013', 'Egg-and-Lemon Soup', 'American', ["section-book-betty-intl"], 'eggs', 'soup', 45, 'The Greeks claim soupa avgolemeno as their very own—but this fragrant broth is prized in many areas of North Africa and the Middle East, from Casablanca to Beirut.', [I('can (46 ounces) chicken broth', 1, '', 'Pantry'), I('uncooked regular rice', 0.3333333333333333, 'cups', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('eggs, beaten', 2, '', 'Dairy & Eggs'), I('lemon juice', 3, 'tbsp', 'Produce'), I('snipped parsley, chives or mint', 2, 'tbsp', 'Produce')], ['Heat chicken broth, rice and salt to boiling in 3-quart saucepan, stirring once or twice; reduce heat.', 'Cover and simmer until rice is tender, about 14 minutes.', 'Mix eggs and lemon juice.', 'Stir 1/4 cup of the hot broth into egg mixture; stir into broth mixture in saucepan.', 'Cook and stir over low heat until slightly thickened, 2 to 3 minutes. (Do not boil or eggs will curdle.)', 'Garnish each serving with parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-014', 'English Cake Roll', 'American', ["section-book-betty-intl"], 'eggs', 'dessert', 45, 'A most unusual accent—whipped cream flavored with tea!—and a sublime marmalade filling make this British inspiration a real conversation piece.', [I('eggs', 3, '', 'Dairy & Eggs'), I('granulated sugar', 1, 'cups', 'Pantry'), I('water', 0.3333333333333333, 'cups', 'Other'), I('vanilla', 1, 'tsp', 'Pantry'), I('all-purpose flour or 1 cup cake flour', 0.75, 'cups', 'Pantry'), I('baking powder', 1, 'tsp', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('orange or lemon marmalade', 0.75, 'cups', 'Pantry'), I('Tea Whipped Cream', 1, '', 'Other'), I('Powdered sugar', 1, '', 'Pantry'), I('chilled whipping cream', 1, 'cups', 'Dairy & Eggs'), I('powdered sugar', 3, 'tbsp', 'Pantry'), I('instant tea', 2, 'tbsp', 'Pantry'), I('vanilla', 0.5, 'tsp', 'Pantry')], ['Heat oven to 375°.', 'Line jelly roll pan, 15 1/2 x 10 1/2 x 1 inch, with aluminum foil or waxed paper; grease generously.', 'Beat eggs in small mixer bowl on high speed until thick and lemon colored, about 5 minutes.', 'Pour eggs into large mixer bowl.', 'Beat in granulated sugar gradually.', 'Beat in water and vanilla on low speed.', 'Add flour, baking powder and salt gradually, beating just until batter is smooth.', 'Pour into pan.', 'Bake until wooden pick inserted in center comes out clean, 12 to 15 minutes.', 'Immediately loosen cake from edges of pan; invert on towel sprinkled generously with powdered sugar.', 'Carefully remove foil.', 'Trim off stiff edges if necessary.', 'While hot, carefully roll cake and towel from narrow end.', 'Cool on wire rack at least 30 minutes.', 'Unroll cake; remove towel.', 'Spread marmalade over cake.', 'Cover marmalade with Tea Whipped Cream; roll up. (See diagram.)', 'Sprinkle with powdered sugar.', 'Refrigerate until serving time.', 'Tea Whipped Cream: Beat all ingredients in chilled bowl until stiff.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-015', 'English Plum Pudding', 'American', ["section-book-betty-intl"], 'beef', 'dessert', 45, 'England\'s favorite holiday dessert, immortalized in Charles Dickens\' A Christmas Carol, has delighted British food lovers since the Middle Ages, when it was often served with meats as a first-course "porridge."', [I('all-purpose flour', 0.5, 'cups', 'Pantry'), I('ground cinnamon', 0.5, 'tsp', 'Herbs & Spices'), I('ground nutmeg', 0.125, 'tsp', 'Herbs & Spices'), I('ground cloves', 0.125, 'tsp', 'Herbs & Spices'), I('baking soda', 0.5, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('raisins', 1, 'cups', 'Pantry'), I('currants', 0.5, 'cups', 'Pantry'), I('cut-up candied fruit peel', 0.25, 'cups', 'Pantry'), I('cut-up candied cherries', 0.25, 'cups', 'Pantry'), I('chopped walnuts', 0.25, 'cups', 'Pantry'), I('soft bread crumbs', 0.75, 'cups', 'Bakery'), I('ground suet (4 ounces)', 1, 'cups', 'Meat & Seafood'), I('packed brown sugar', 0.5, 'cups', 'Pantry'), I('eggs, beaten', 2, '', 'Dairy & Eggs'), I('brandy', 1, 'tbsp', 'Pantry'), I('brandy (optional)', 0.25, 'cups', 'Pantry'), I('Hard Sauce', 1, '', 'Other'), I('margarine or butter, softened', 0.5, 'cups', 'Dairy & Eggs'), I('powdered sugar', 1, 'cups', 'Pantry'), I('brandy', 2, 'tbsp', 'Pantry'), I('water', 1, '', 'Other')], ['Mix flour, spices, baking soda and salt.', 'Stir in fruit, walnuts and bread crumbs.', 'Mix suet, brown sugar, eggs and 1 tablespoon brandy; stir into flour-fruit mixture.', 'Pour into well-greased 4-cup mold; cover with aluminum foil.', 'Place mold on rack in Dutch oven; pour boiling water into Dutch oven to rack level.', 'Cover and boil over low heat until wooden pick inserted in center comes out clean, about 3 hours. (Add boiling water if necessary.)', 'Remove mold from Dutch oven; unmold.', 'Heat 1/4 cup brandy until warm; ignite and pour over pudding.', 'Serve with Hard Sauce.', 'Hard Sauce: Beat 1/2 cup margarine or butter, softened, 1 cup powdered sugar and 2 tablespoons brandy until smooth.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-016', 'Fish and Collard Greens', 'American', ["section-book-betty-intl"], 'fish', 'fish', 45, 'This fish stew comes from the Congo region of central Africa, where it is often served with yams or sweet potatoes.', [I('medium onions, sliced', 2, '', 'Produce'), I('green pepper, sliced', 1, '', 'Produce'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('package (10 ounces) frozen collard greens', 1, '', 'Frozen'), I('water', 2, 'tbsp', 'Other'), I('fish fillets', 1, 'lb', 'Meat & Seafood'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('paprika', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('lemon wedges (if desired)', 1, '', 'Produce')], ['Cook and stir onions and green pepper in margarine in 3-quart saucepan until onion is tender, about 3 minutes.', 'Add collard greens and water.', 'Heat to boiling; separate greens with fork.', 'Reduce heat.', 'Cover and simmer 5 minutes.', 'Cut fish into strips, 4 x 3/4 inches each; add to vegetables.', 'Sprinkle with salt, paprika and pepper.', 'Heat to boiling; reduce heat.', 'Cover and simmer until fish flakes easily with fork, about 5 minutes.', 'Garnish with lemon wedges if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-017', 'Fish with Sour Cream', 'American', ["section-book-betty-intl"], 'fish', 'dessert', 45, 'In Hungary as in Austria, small "boiling" potatoes served in their bright red skins often accompany betyar fogas.', [I('fish fillets', 1, 'lb', 'Meat & Seafood'), I('mushrooms, sliced', 4, 'oz', 'Produce'), I('small onion, chopped', 1, '', 'Produce'), I('margarine or butter', 1, 'tbsp', 'Dairy & Eggs'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices'), I('dairy sour cream', 0.5, 'cups', 'Dairy & Eggs'), I('grated Parmesan cheese', 3, 'tbsp', 'Dairy & Eggs'), I('dry bread crumbs', 2, 'tbsp', 'Bakery'), I('Paprika', 1, '', 'Herbs & Spices'), I('Snipped parsley', 1, '', 'Produce')], ['If fish fillets are large, cut into serving pieces.', 'Pat fish dry with paper towels; arrange in ungreased oblong baking dish, 12 x 7 1/2 x 2 inches.', 'Cook and stir mushrooms and onion in margarine until mushrooms are golden, about 3 minutes.', 'Spoon mushroom mixture over fish; sprinkle with salt and pepper.', 'Mix sour cream and cheese; spread over mushroom mixture.', 'Sprinkle with bread crumbs.', 'Cook uncovered in 350° oven until fish flakes easily with fork, 25 to 30 minutes.', 'Sprinkle with paprika and parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-018', 'Flaming Cheese', 'American', ["section-book-betty-intl"], 'veg', 'roast', 45, 'Few hot appetizers are easier or more glamorous than this Greek specialty.', [I('Kasseri or Kefalotiri cheese', 0.5, 'lb', 'Dairy & Eggs'), I('margarine or butter, melted', 1, 'tbsp', 'Dairy & Eggs'), I('brandy', 2, 'tbsp', 'Pantry'), I('lemon', 0.5, '', 'Produce'), I('Cocktail rye bread or assorted crackers', 1, '', 'Bakery')], ['Cut cheese into 3 wedges; place in shallow heatproof serving dish.', 'Brush cheese with margarine.', 'Set oven control to broil and/or 550°.', 'Broil cheese with top 4 to 6 inches from heat until bubbly light brown, 5 to 6 minutes.', 'Heat brandy until warm; pour over cheese.', 'Ignite immediately.', 'Squeeze lemon over cheese.', 'Cut wedges into halves.', 'Serve with rye bread.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-019', 'French Potato Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'The French regarded the potato with suspicion until the late eighteenth century, when the vegetable was praised by the French food scientist Antoine Auguste Parmentier as an excellent food to be used in times of poor harvests.', [I('medium potatoes (about 2 pounds)', 6, '', 'Produce'), I('clove garlic, cut into halves', 1, '', 'Produce'), I('beef or chicken bouillon', 0.25, 'tsp', 'Pantry'), I('hot water', 0.3333333333333333, 'cups', 'Other'), I('dry white wine', 0.3333333333333333, 'cups', 'Pantry'), I('Tarragon Dressing', 1, '', 'Other'), I('snipped parsley', 3, 'tbsp', 'Produce'), I('olive or vegetable oil', 3, 'tbsp', 'Pantry'), I('tarragon vinegar', 2, 'tbsp', 'Pantry'), I('snipped chives', 2, 'tsp', 'Produce'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('dark prepared mustard', 1, 'tsp', 'Pantry'), I('dried tarragon leaves', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices'), I('tomato wedges (if desired)', 1, '', 'Produce'), I('sliced cooked luncheon meat (if desired)', 1, '', 'Meat & Seafood')], ['Heat 1 inch salted water (1/2 teaspoon salt to 1 cup water) to boiling.', 'Add potatoes.', 'Heat to boiling; reduce heat.', 'Cover and cook until tender, 30 to 35 minutes.', 'Drain and cool.', 'Rub 2-quart bowl with garlic; discard garlic.', 'Cut potatoes into 1/4-inch slices; place in bowl.', 'Dissolve bouillon in hot water; add wine.', 'Pour over potatoes.', 'Cover and refrigerate, stirring once or twice; drain.', 'Prepare Tarragon Dressing; gently toss with potatoes.', 'Sprinkle with parsley.', 'Garnish with tomato wedges and sliced cooked luncheon meat if desired.', 'Tarragon Dressing: Shake all ingredients in tightly covered jar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-020', 'Fresh Mushroom Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'This creamy mushroom salad from Finland goes well with roast beef or pork.', [I('mushrooms, sliced', 1, 'lb', 'Produce'), I('snipped chives', 2, 'tbsp', 'Produce'), I('whipping cream or half-and-half', 0.25, 'cups', 'Dairy & Eggs'), I('sugar', 2, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('Dash of pepper', 1, '', 'Herbs & Spices'), I('lettuce cups (if desired)', 1, '', 'Produce'), I('water', 1, '', 'Other')], ['Heat 1 inch salted water (1/2 teaspoon salt to 1 cup water) to boiling.', 'Add mushrooms.', 'Heat to boiling; reduce heat.', 'Cover and simmer 1 minute.', 'Drain and chill.', 'Add chives.', 'Mix remaining ingredients.', 'Pour over mushrooms and chives; toss.', 'Serve in lettuce cups if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-021', 'Fried Potato Bread', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'This thin, soft griddle-fried bread from Norway is served warm or cold, spread with butter and sometimes sprinkled with brown sugar—then rolled up or folded into small serving-size portions.', [I('hot mashed potatoes (no milk, margarine or salt added)', 5, 'cups', 'Produce'), I('shortening', 0.25, 'cups', 'Pantry'), I('milk', 2, 'tbsp', 'Dairy & Eggs'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('all-purpose flour', 2, 'cups', 'Pantry')], ['Beat mashed potatoes, shortening, milk and salt until no lumps remain.', 'Cover and refrigerate until completely chilled, at least 4 hours.', 'Turn potato mixture onto floured surface; knead in flour. (Dough will be soft.)', 'Divide into 20 equal parts; shape each part into a ball. (For best results, work with 4 or 5 balls at a time; cover and refrigerate remaining balls until needed.)', 'Shape each ball into a flattened round on heavily floured board.', 'Roll each round as thin as possible into 10- to 12-inch circle with floured stockinet-covered rolling pin or lefse rolling pin. (See photograph.)', 'Lift dough occasionally with spatula to make sure it is not sticking, adding flour as needed.', 'Heat ungreased griddle or lefse baker to 400°.', 'Cook until blisters form and brown spots appear on bottom, about 1 minute on each side. (Do not overcook. Lefse should be soft, not crisp.)', 'Stack between 2 towels to prevent drying.', 'Wrap in plastic wrap and refrigerate no longer than 3 days or freeze no longer than 1 month.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-022', 'Fried Tomatoes', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'When your budget suggests a simple, low-cost supper, give it a fragrant Greek accent—serve these tomatoes with Scrambled Eggs with Rice (page 158).', [I('firm ripe medium tomatoes', 4, '', 'Produce'), I('fine cracker crumbs', 0.5, 'cups', 'Bakery'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('olive or vegetable oil', 0.25, 'cups', 'Pantry')], ['Cut tomatoes into 3/4-inch slices.', 'Mix cracker crumbs, salt and pepper.', 'Coat tomato slices with crumb mixture.', 'Heat oil in 12-inch skillet until hot.', 'Cook tomato slices in oil, turning once, until golden brown on both sides.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-023', 'German Apple Pancakes', 'American', ["section-book-betty-intl"], 'eggs', 'dessert', 45, 'Giant apple pancakes are baked in the oven for twenty to twenty-five minutes, eliminating last-minute fuss when planning a party brunch.', [I('eggs', 4, '', 'Dairy & Eggs'), I('all-purpose flour', 0.75, 'cups', 'Pantry'), I('milk', 0.75, 'cups', 'Dairy & Eggs'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('medium apples, thinly sliced', 2, '', 'Produce'), I('sugar', 0.25, 'cups', 'Pantry'), I('ground cinnamon', 0.25, 'tsp', 'Herbs & Spices')], ['Heat oven to 400°.', 'Place 2 round layer pans, 9 x 1 1/2 inches, in oven.', 'Beat eggs, flour, milk and salt in small mixer bowl on medium speed 1 minute.', 'Remove pans from oven.', 'Place 2 tablespoons margarine in each pan; rotate pans until margarine is melted and coats sides of pans.', 'Arrange half the apple slices in each pan; divide batter evenly between pans.', 'Mix sugar and cinnamon; sprinkle 2 tablespoons sugar mixture over batter in each pan.', 'Bake uncovered until puffed and golden brown, 20 to 25 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-024', 'Glazed Carrots', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'The French use Glazed Carrots liberally as an attractive accompaniment to roasts.', [I('medium carrots (about 1 1/4 pounds)', 8, '', 'Produce'), I('water', 0.75, 'cups', 'Other'), I('margarine or butter', 2, 'tbsp', 'Dairy & Eggs'), I('sugar', 1, 'tbsp', 'Pantry'), I('instant beef bouillon', 0.5, 'tsp', 'Pantry'), I('Dash of pepper', 1, '', 'Herbs & Spices'), I('Snipped parsley', 1, '', 'Produce')], ['Cut carrots into 2-inch pieces.', 'Heat carrots and remaining ingredients except parsley to boiling; reduce heat.', 'Cover and simmer until carrots are tender, about 25 minutes.', 'Remove carrots and boil rapidly to reduce liquid to glaze consistency.', 'Add carrots; turn to coat evenly with glaze.', 'Sprinkle with parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-025', 'Glazed Chicken Wings', 'American', ["section-book-betty-intl"], 'chicken', 'roast', 45, 'Inexpensive chicken wings make a delectable appetizer when marinated in honey and soy sauce, for a pungent Chinese accent, serve with Hot Mustard Sauce (page 8).', [I('chicken wings (about 15)', 3, 'lb', 'Meat & Seafood'), I('soy sauce', 0.6666666666666666, 'cups', 'Pantry'), I('honey', 0.5, 'cups', 'Pantry'), I('vegetable oil', 2, 'tbsp', 'Pantry'), I('five spice powder', 2, 'tsp', 'Pantry'), I('cloves garlic, crushed', 2, '', 'Produce')], ['Cut each chicken wing at joints to make three pieces; discard tips or save for use in making stock (page 101).', 'Place chicken wings in shallow glass or plastic dish.', 'Mix remaining ingredients; pour over chicken.', 'Cover and refrigerate, turning chicken occasionally, at least 1 hour.', 'Arrange chicken on rack in foil-lined broiler pan; reserve marinade.', 'Brush chicken with reserved marinade.', 'Cook in 375° oven 30 minutes.', 'Turn chicken and cook, brushing occasionally with marinade, until done, about 30 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-026', 'Greek Honey Twists', 'American', ["section-book-betty-intl"], 'eggs', 'dessert', 45, 'The traditional way to serve these Greek cookies is to drizzle them with honey, then sprinkle with cinnamon, finely chopped almonds or walnuts.', [I('eggs, beaten', 3, '', 'Dairy & Eggs'), I('vegetable oil', 2, 'tbsp', 'Pantry'), I('baking powder', 0.5, 'tsp', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('1 3/4 to 2 cups all-purpose flour', 1, '', 'Pantry'), I('Vegetable oil', 1, '', 'Pantry'), I('honey', 0.25, 'cups', 'Pantry'), I('water', 1, 'tbsp', 'Other'), I('Ground cinnamon', 1, '', 'Herbs & Spices')], ['Mix eggs, 2 tablespoons oil, the baking powder and salt in large bowl.', 'Gradually stir in enough flour to make a very stiff dough.', 'Knead 5 minutes.', 'Roll half the dough at a time as thin as possible on well-floured surface with stockinet-covered rolling pin.', 'Cut into strips, 8 x 1 inch.', 'Tie strips loosely. (Cover with damp towel to prevent drying.)', 'Heat oil (2 to 3 inches) to 375°.', 'Fry 3 to 5 twists at a time until golden brown, turning once, about 45 seconds on each side.', 'Drain on paper towels.', 'Heat honey and water to boiling; boil 1 minute.', 'Cool slightly.', 'Drizzle over twists; sprinkle with cinnamon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-027', 'Green Banana Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'Green bananas are used as vegetables throughout Latin America.', [I('green (unripe) bananas, peeled', 3, '', 'Produce'), I('water', 2, 'cups', 'Other'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('medium carrots, shredded', 2, '', 'Produce'), I('small cucumber, sliced', 1, '', 'Produce'), I('medium tomato, chopped', 1, '', 'Produce'), I('avocado, cubed', 1, '', 'Produce'), I('stalk celery, sliced', 1, '', 'Produce'), I('Vinaigrette Dressing (page 204)', 1, '', 'Pantry')], ['Heat bananas, water and salt to boiling; reduce heat.', 'Cover and simmer until bananas are tender, about 5 minutes.', 'Drain and cool.', 'Cut bananas crosswise into 1/2-inch slices.', 'Toss bananas and remaining ingredients with Vinaigrette Dressing.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-028', 'Hungarian Beef Goulash', 'American', ["section-book-betty-intl"], 'beef', 'soup', 45, 'Bogracs means cauldron; gulyas means herdsman\'s meat.', [I('vegetable oil or bacon fat', 2, 'tbsp', 'Pantry'), I('beef boneless chuck, tip or round, cut into 3/4-inch cubes', 1.5, 'lb', 'Meat & Seafood'), I('water', 2, 'cups', 'Other'), I('can (8 ounces) tomatoes', 1, '', 'Pantry'), I('medium onions, chopped', 3, '', 'Produce'), I('clove garlic, chopped', 1, '', 'Produce'), I('paprika', 2, 'tsp', 'Herbs & Spices'), I('salt', 2, 'tsp', 'Herbs & Spices'), I('instant beef bouillon', 1, 'tsp', 'Pantry'), I('caraway seed', 0.5, 'tsp', 'Pantry'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('medium potatoes, cut into 1 1/2-inch pieces', 2, '', 'Produce'), I('green peppers, cut into 1-inch pieces', 2, '', 'Produce'), I('French bread or rolls', 1, '', 'Bakery')], ['Heat oil in Dutch oven or 12-inch skillet until hot.', 'Cook and stir beef in hot oil until brown, about 15 minutes; drain.', 'Add water, tomatoes (with liquid), onions, garlic, paprika, salt, bouillon, caraway seed and pepper.', 'Break up tomatoes with fork.', 'Heat to boiling; reduce heat.', 'Cover and simmer 1 hour.', 'Add potatoes; cover and simmer until beef and potatoes are tender, about 30 minutes.', 'Add green peppers; cover and simmer until tender, 8 to 10 minutes.', 'Serve in soup bowls with chunks of French bread for dipping into hot broth.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-029', 'Indian Flat Bread', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'Naan is popular in both India and Pakistan and is found throughout the central steppes of Asia.', [I('all-purpose flour', 2, 'cups', 'Pantry'), I('unflavored yogurt', 0.25, 'cups', 'Dairy & Eggs'), I('egg, slightly beaten', 1, '', 'Dairy & Eggs'), I('baking powder', 1.5, 'tsp', 'Pantry'), I('sugar', 1, 'tsp', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('baking soda', 0.125, 'tsp', 'Pantry'), I('milk', 0.5, 'cups', 'Dairy & Eggs'), I('Ghee (page 218) or vegetable oil', 1, '', 'Pantry'), I('Poppy seed', 1, '', 'Herbs & Spices')], ['Mix all ingredients except milk, Ghee and poppy seed.', 'Stir in enough milk to make a soft dough.', 'Turn dough onto lightly floured surface; knead until smooth, about 5 minutes.', 'Place in greased bowl; turn greased side up.', 'Cover; let rest in warm place 3 hours.', 'Divide dough into 6 or 8 equal parts.', 'Flatten each part on lightly floured surface, rolling it into a 6- x 4-inch leaf shape about 1/4 inch thick.', 'Brush with Ghee; sprinkle with poppy seed.', 'Place 2 cookie sheets in oven; heat oven to 450°.', 'Remove hot cookie sheets from oven; place breads on cookie sheets.', 'Bake until firm, 6 to 8 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-030', 'Indonesian Fried Rice', 'American', ["section-book-betty-intl"], 'seafood', 'fish', 45, 'This Indonesian version of "fried rice" bears little resemblance to Chinese-restaurant fried rice.', [I('medium onions, chopped', 2, '', 'Produce'), I('vegetable oil', 3, 'tbsp', 'Pantry'), I('cold cooked rice (page 253)', 4, 'cups', 'Pantry'), I('finely chopped fully cooked smoked ham', 1, 'cups', 'Meat & Seafood'), I('curry powder', 2, 'tsp', 'Herbs & Spices'), I('ground coriander', 0.25, 'tsp', 'Herbs & Spices'), I('ground cumin', 0.25, 'tsp', 'Herbs & Spices'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('can (5 ounces) tiny shrimp, drained', 1, '', 'Pantry'), I('snipped parsley', 2, 'tbsp', 'Produce')], ['Cook and stir onions in oil in 12-inch skillet until tender.', 'Add rice, ham, curry powder, coriander, cumin and salt.', 'Cook and stir until rice is golden brown, 10 to 15 minutes.', 'Stir in shrimp and parsley.', 'Cover and cook 1 minute.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-031', 'Italian Coffee Cake', 'American', ["section-book-betty-intl"], 'eggs', 'dessert', 45, 'Panettone originated in Milan but is now popular throughout Italy, especially in the Lombardy region.', [I('packages active dry yeast', 2, '', 'Pantry'), I('warm water (105 to 115°)', 1, 'cups', 'Pantry'), I('sugar', 0.5, 'cups', 'Pantry'), I('margarine or butter, softened', 0.5, 'cups', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('grated lemon peel', 1, 'tsp', 'Produce'), I('vanilla', 1, 'tsp', 'Pantry'), I('5 to 5 1/2 cups all-purpose flour', 1, '', 'Pantry'), I('golden raisins', 0.5, 'cups', 'Pantry'), I('chopped citron', 0.5, 'cups', 'Pantry'), I('pine nuts or walnuts (optional)', 2, 'tbsp', 'Pantry'), I('Margarine or butter, softened', 1, '', 'Dairy & Eggs')], ['Dissolve yeast in warm water in large bowl.', 'Stir in sugar, 1/2 cup margarine, the eggs, salt, lemon peel, vanilla and 2 1/2 cups of the flour.', 'Beat until smooth.', 'Stir in raisins, citron, pine nuts and enough remaining flour to make dough easy to handle.', 'Turn dough onto lightly floured surface; knead until smooth and elastic, about 5 minutes.', 'Place in greased bowl; turn greased side up.', 'Cover; let rise in warm place until double, 1 1/2 to 2 hours. (Dough is ready if indentation remains when touched.)', 'Punch down dough; divide into halves.', 'Shape each half into round loaf, about 7 inches in diameter.', 'Place loaves in 2 ungreased round layer pans, 8 x 1 1/2 inches.', 'Cut a cross 1/2 inch deep on top of each loaf.', 'Generously grease one side of a strip of heavy brown paper, about 25 x 4 inches.', 'Fit around inside of pan, forming a collar; fasten with paper clip.', 'Repeat with second loaf.', 'Cover; let rise until double, about 1 hour.', 'Heat oven to 350°.', 'Bake loaves until golden brown, 35 to 45 minutes.', 'Remove paper.', 'Brush tops with margarine.', 'Cool on rack.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-032', 'Italian Green Bean Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'This crisp, fresh salad features snappy green beans—use yellow, too, when in season.', [I('green beans', 1, 'lb', 'Produce'), I('Vinaigrette Dressing', 1, '', 'Other'), I('Lettuce (optional)', 1, '', 'Produce'), I('tomatoes, cut into wedges', 2, '', 'Produce'), I('small onion, sliced', 1, '', 'Produce'), I('grated Parmesan cheese', 0.25, 'cups', 'Dairy & Eggs'), I('Ripe olives', 1, '', 'Produce'), I('olive or vegetable oil', 0.3333333333333333, 'cups', 'Pantry'), I('wine vinegar', 2, 'tbsp', 'Pantry'), I('clove garlic, chopped', 1, '', 'Produce'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('prepared dark mustard', 0.5, 'tsp', 'Pantry'), I('Dash of pepper', 1, '', 'Herbs & Spices'), I('water', 1, '', 'Other')], ['Remove ends from beans.', 'If beans are large, cut French style into lengthwise strips.', 'Heat beans and 1 inch salted water (1/2 teaspoon salt to 1 cup water) to boiling.', 'Cook uncovered 5 minutes.', 'Cover and cook until tender, whole 10 to 15 minutes, French style 5 to 10 minutes; drain.', 'Prepare Vinaigrette Dressing.', 'Pour over warm beans and toss.', 'Cover and refrigerate at least 2 hours.', 'Remove beans to lettuce-lined plate with slotted spoon.', 'Add tomatoes and onion.', 'Sprinkle with cheese; garnish with olives.', 'Vinaigrette Dressing: Mix all ingredients.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-033', 'Italian Rice and Peas', 'American', ["section-book-betty-intl"], 'pork', 'bowl', 45, 'One of the best-known of Venetian dishes, risi e bisi makes a fine party side dish.', [I('small onion, chopped', 1, '', 'Produce'), I('margarine or butter', 2, 'tbsp', 'Dairy & Eggs'), I('package (10 ounces) frozen green peas', 1, '', 'Frozen'), I('water', 2, 'cups', 'Other'), I('uncooked regular rice', 1, 'cups', 'Pantry'), I('fully cooked smoked ham, chopped (about 1/2 cup)', 2, 'oz', 'Meat & Seafood'), I('instant chicken bouillon', 1, 'tsp', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('grated Parmesan cheese', 0.25, 'cups', 'Dairy & Eggs')], ['Cook and stir onion in margarine in 2-quart saucepan until tender.', 'Stir in remaining ingredients except cheese.', 'Heat to boiling, stirring once or twice; reduce heat.', 'Cover and simmer 14 minutes. (Do not lift cover or stir.)', 'Remove from heat.', 'Fluff rice lightly with fork; cover and let steam 5 to 10 minutes.', 'Stir in cheese lightly with fork.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-034', 'Italian Zucchini Omelet', 'American', ["section-book-betty-intl"], 'eggs', 'roast', 45, 'The Italian omelet, called frittata, is one of the easiest omelets to make.', [I('eggs', 6, '', 'Dairy & Eggs'), I('water', 0.25, 'cups', 'Other'), I('snipped parsley', 3, 'tbsp', 'Produce'), I('soft bread crumbs', 3, 'tbsp', 'Bakery'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('clove garlic, finely chopped', 1, '', 'Produce'), I('olive or vegetable oil', 2, 'tbsp', 'Pantry'), I('1/4-inch slices zucchini (1 medium)', 1, 'cups', 'Produce'), I('Flour', 1, '', 'Pantry'), I('Grated Parmesan cheese', 1, '', 'Dairy & Eggs')], ['Beat eggs, water, parsley, bread crumbs, salt and garlic.', 'Heat oil in 8-inch skillet over medium heat until hot.', 'Coat zucchini with flour; cook until golden, about 2 minutes on each side.', 'Pour egg mixture over zucchini.', 'Cook until eggs are thickened throughout but still moist, 3 to 5 minutes.', 'Gently lift edge with fork so that uncooked portion can flow to bottom.', 'Sprinkle with cheese.', 'Set oven control to broil and/or 550°.', 'Broil omelet with top 5 inches from heat until golden brown, 3 to 4 minutes.', 'Loosen edge with spatula; slip cheese side up onto serving plate.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-035', 'Latin American Fish Soup', 'American', ["section-book-betty-intl"], 'fish', 'soup', 45, 'Chicken broth provides a rich, full-bodied flavor to this Latin American interpretation of the fish soups found throughout the Mediterranean countries.', [I('medium onions, chopped', 2, '', 'Produce'), I('cloves garlic, crushed', 2, '', 'Produce'), I('olive or vegetable oil', 2, 'tbsp', 'Pantry'), I('fish fillets, cut into 1-inch pieces', 1.5, 'lb', 'Meat & Seafood'), I('cans (10 3/4 ounces each) condensed chicken broth', 2, '', 'Pantry'), I('soup cans water', 2, '', 'Pantry'), I('tomatoes, coarsely chopped', 3, '', 'Produce'), I('green peppers, chopped', 2, '', 'Produce'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('dried oregano leaves', 0.5, 'tsp', 'Herbs & Spices'), I('ground red pepper', 0.5, 'tsp', 'Herbs & Spices')], ['Cook and stir onions and garlic in oil in Dutch oven until onion is tender; add remaining ingredients.', 'Heat to boiling; reduce heat.', 'Cover and simmer until fish flakes easily with fork, about 5 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-036', 'Little Latin Meatballs', 'American', ["section-book-betty-intl"], 'beef', 'bowl', 45, 'Served as appetizers in many Latin American countries and in Spain, these perky meatballs can be made in advance and kept warm in the chafing dish.', [I('jalepeño chilies', 2, '', 'Produce'), I('ground beef', 1, 'lb', 'Meat & Seafood'), I('egg', 1, '', 'Dairy & Eggs'), I('dry bread crumbs', 0.5, 'cups', 'Bakery'), I('milk', 0.25, 'cups', 'Dairy & Eggs'), I('shredded Monterey Jack or Cheddar cheese', 0.25, 'cups', 'Dairy & Eggs'), I('small onion, finely chopped', 1, '', 'Produce'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('Salsa', 1, '', 'Other'), I('can (8 ounces) tomato sauce', 1, '', 'Pantry'), I('medium tomato, chopped', 1, '', 'Produce'), I('cloves garlic, finely chopped', 2, '', 'Produce'), I('snipped parsley', 2, 'tbsp', 'Produce'), I('vinegar', 1, 'tbsp', 'Pantry'), I('ground cumin', 0.125, 'tsp', 'Herbs & Spices'), I('salt', 0.125, 'tsp', 'Herbs & Spices')], ['Remove stems, seeds and membranes from chilies; chop chilies.', 'Mix chilies, beef, egg, bread crumbs, milk, cheese, onion, salt and pepper.', 'Shape mixture into 1-inch balls.', 'Place meatballs in ungreased oblong pan, 13 x 9 x 2 inches.', 'Cook uncovered in 400° oven until brown, 15 to 20 minutes.', 'Place meatballs in chafing dish.', 'Pour Salsa over meatballs.', 'Salsa: Heat all ingredients in 1-quart saucepan, stirring occasionally, until hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-037', 'Oyster Casserole', 'American', ["section-book-betty-intl"], 'seafood', 'fish', 45, 'From Mexico\'s dramatic Pacific Coast—a creamy oyster-and-tomato casserole flavored with cumin, allspice and red pepper.', [I('shucked select or large oysters, drained', 1, 'pint', 'Meat & Seafood'), I('tomatoes, chopped', 2, '', 'Produce'), I('half-and-half', 0.5, 'cups', 'Dairy & Eggs'), I('cracker crumbs (about 20 crackers)', 2, 'cups', 'Bakery'), I('margarine or butter, melted', 0.5, 'cups', 'Dairy & Eggs'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('ground cumin', 0.5, 'tsp', 'Herbs & Spices'), I('ground allspice', 0.25, 'tsp', 'Herbs & Spices'), I('ground red pepper', 0.125, 'tsp', 'Herbs & Spices'), I('Lemon or lime wedges', 1, '', 'Produce')], ['Mix oysters and tomatoes; arrange in ungreased oblong baking dish, 11 x 7 x 1 1/2 inches.', 'Pour 1/4 cup of the half-and-half over mixture.', 'Mix remaining ingredients except lemon wedges; sprinkle over oysters and tomatoes.', 'Pour remaining half-and-half over crumb mixture.', 'Cook uncovered in 375° oven until light brown, about 30 minutes.', 'Garnish with lemon wedges.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-038', 'Pineapple Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'The cooking of Thailand began to gain many fans in both France and the United States in the early 1970\'s; today Thai restaurants and food buffs can be found from Los Angeles to Monte Carlo.', [I('olive or vegetable oil', 0.3333333333333333, 'cups', 'Pantry'), I('lemon juice', 2, 'tbsp', 'Produce'), I('soy sauce', 1, 'tbsp', 'Pantry'), I('1 to 2 teaspoons packed brown sugar', 1, '', 'Pantry'), I('small pineapple', 1, '', 'Produce'), I('tart red apple, diced', 1, '', 'Produce'), I('green onions (with tops), sliced', 3, '', 'Produce'), I('small bunch romaine, shredded', 1, '', 'Produce')], ['Shake oil, lemon juice, soy sauce and brown sugar in tightly covered jar.', 'Twist top from pineapple; cut pineapple into fourths.', 'Cut fruit from rind; remove core and any "eyes." Slice each fourth lengthwise; cut crosswise into chunks.', 'Toss pineapple chunks, apple and green onions with dressing.', 'Place romaine in shallow bowl; mound fruit mixture in center.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-039', 'Portuguese Sweet Bread', 'American', ["section-book-betty-intl"], 'eggs', 'bowl', 45, 'The Portuguese are famous for their Christmas bread and their Easter bread (which contains decorative Easter eggs baked into the loaf!).', [I('packages active dry yeast', 2, '', 'Pantry'), I('warm water (105 to 115°)', 0.25, 'cups', 'Pantry'), I('lukewarm milk (scalded, then cooled)', 1, 'cups', 'Dairy & Eggs'), I('sugar', 0.75, 'cups', 'Pantry'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('eggs', 3, '', 'Dairy & Eggs'), I('margarine or butter, softened', 0.5, 'cups', 'Dairy & Eggs'), I('5 1/2 to 6 cups all-purpose flour', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('sugar', 1, 'tsp', 'Pantry')], ['Dissolve yeast in warm water in large bowl.', 'Stir in milk, 3/4 cup sugar, the salt, 3 eggs, the margarine and 3 cups of the flour.', 'Beat until smooth.', 'Stir in enough remaining flour to make dough easy to handle.', 'Turn dough onto lightly floured surface; knead until smooth and elastic, about 5 minutes.', 'Place in greased bowl; turn greased side up.', 'Cover; let rise in warm place until double, 1 1/2 to 2 hours. (Dough is ready if indentation remains when touched.)', 'Punch down dough; divide into halves.', 'Shape each half into a round, slightly flat loaf.', 'Place each loaf in greased round layer pan, 9 x 1 1/2 inches.', 'Cover; let rise until double, about 1 hour.', 'Heat oven to 350°.', 'Beat 1 egg slightly; brush over loaves.', 'Sprinkle with 1 teaspoon sugar.', 'Bake until loaves are golden brown, 35 to 45 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-040', 'Red Cabbage with Apples', 'American', ["section-book-betty-intl"], 'veg', 'roast', 45, 'Tart boiled red cabbage and apples provide a refreshing change of pace when served with rich dishes such as roast pork or duck.', [I('tart red apples, sliced', 2, '', 'Produce'), I('margarine or butter', 3, 'tbsp', 'Dairy & Eggs'), I('medium head red cabbage, coarsely shredded (about 8 cups)', 1, '', 'Produce'), I('water', 0.25, 'cups', 'Other'), I('red wine vinegar', 0.25, 'cups', 'Pantry'), I('sugar', 2, 'tbsp', 'Pantry'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices')], ['Cook and stir apples in margarine in Dutch oven over medium heat 5 minutes.', 'Stir in remaining ingredients.', 'Heat to boiling; reduce heat.', 'Cover and simmer until cabbage is tender, 35 to 40 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-041', 'Rice Milan Style', 'American', ["section-book-betty-intl"], 'veg', 'bowl', 45, 'This rice recipe has become so famous throughout Italy that it is sometimes simply called risotto—a word often used by non-Italian chefs for rice.', [I('uncooked regular rice', 1, 'cups', 'Pantry'), I('small onion, chopped', 1, '', 'Produce'), I('chopped beef marrow (optional)', 1, 'tbsp', 'Meat & Seafood'), I('margarine or butter', 3, 'tbsp', 'Dairy & Eggs'), I('water', 2, 'cups', 'Other'), I('instant chicken bouillon', 2, 'tsp', 'Pantry'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('Dash of ground saffron', 1, '', 'Herbs & Spices'), I('grated Parmesan cheese', 0.25, 'cups', 'Dairy & Eggs')], ['Cook and stir rice, onion and beef marrow in margarine in 2-quart saucepan until rice is golden, 4 to 5 minutes.', 'Stir in remaining ingredients except cheese.', 'Heat to boiling, stirring once or twice; reduce heat.', 'Cover and simmer 14 minutes. (Do not lift cover or stir.)', 'Remove from heat.', 'Stir in cheese lightly with fork; cover and let steam 5 to 10 minutes.', 'Serve rice with additional Parmesan cheese if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-042', 'Rice with Mushrooms', 'American', ["section-book-betty-intl"], 'veg', 'roast', 45, 'A few sliced mushrooms do much to enhance the flavor and appearance of this Italian specialty, which goes well with roast chicken or baked fish.', [I('mushrooms, sliced', 4, 'oz', 'Produce'), I('small onion, chopped', 1, '', 'Produce'), I('small clove garlic, finely chopped', 1, '', 'Produce'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('water', 2, 'cups', 'Other'), I('uncooked regular rice', 1, 'cups', 'Pantry'), I('snipped parsley', 0.25, 'cups', 'Produce'), I('instant chicken bouillon', 2, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('dried basil leaves', 0.25, 'tsp', 'Herbs & Spices'), I('Grated Parmesan or Romano cheese', 1, '', 'Dairy & Eggs')], ['Cook and stir mushrooms, onion and garlic in margarine in 2-quart saucepan until mushrooms and onion are tender.', 'Stir in remaining ingredients except cheese.', 'Heat to boiling, stirring once or twice; reduce heat.', 'Cover and simmer 14 minutes. (Do not lift cover or stir.)', 'Remove from heat.', 'Fluff rice lightly with fork; cover and let steam 5 to 10 minutes.', 'Sprinkle with cheese.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-043', 'Riviera Salad Bowl', 'American', ["section-book-betty-intl"], 'fish', 'dessert', 45, 'From the shining city of Nice, perched on the glamorous French Riviera, comes this refreshing salad, ideal for warm-weather entertaining.', [I('package (10 ounces) frozen French-style green beans', 1, '', 'Frozen'), I('head Boston lettuce, torn into bite-size pieces', 1, '', 'Produce'), I('tomatoes, cut into sixths', 2, '', 'Produce'), I('hard-cooked eggs, cut into fourths', 2, '', 'Dairy & Eggs'), I('can (6 1/2 ounces) tuna, drained', 1, '', 'Pantry'), I('ripe olives', 8, '', 'Produce'), I('can (about 2 ounces) anchovy fillets', 1, '', 'Pantry'), I('Snipped parsley', 1, '', 'Produce'), I('Vinaigrette Dressing', 1, '', 'Other'), I('olive or vegetable oil', 0.5, 'cups', 'Pantry'), I('white wine vinegar', 0.25, 'cups', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('dried basil leaves', 0.5, 'tsp', 'Herbs & Spices'), I('dry mustard', 0.25, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices')], ['Cook beans as directed on package; drain.', 'Cover and refrigerate at least 1 hour.', 'Place lettuce in salad bowl; arrange beans, tomatoes and eggs around edge.', 'Mound tuna in center.', 'Garnish with olives, anchovies and parsley.', 'Serve with Vinaigrette Dressing.', 'Vinaigrette Dressing: Shake ingredients in covered jar; refrigerate.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-044', 'Scottish Skillet Potatoes', 'American', ["section-book-betty-intl"], 'veg', 'roast', 45, 'In the Highlands, "stovies" are often served with cold meats and a frosty pitcher of buttermilk—a traditional Scottish Sunday supper, using the roast remaining from the midday meal.', [I('bacon fat, margarine or butter', 2, 'tbsp', 'Pantry'), I('medium potatoes, thinly sliced (about 4 cups)', 6, '', 'Produce'), I('medium onions, sliced', 2, '', 'Produce'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('snipped parsley', 0.25, 'cups', 'Produce'), I('water', 0.75, 'cups', 'Other')], ['Heat bacon fat in 10-inch skillet until hot.', 'Layer half each of the potato and onion slices in skillet.', 'Sprinkle with half each of the salt, pepper and parsley.', 'Repeat.', 'Add water.', 'Cover and simmer over low heat until potatoes are tender and liquid is absorbed, about 30 minutes. (Add water if necessary.)'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-045', 'Shrimp Balls', 'American', ["section-book-betty-intl"], 'seafood', 'fish', 45, 'A Cantonese specialty, Shrimp Balls are best served piping hot; provide bamboo skewers or wooden picks for ease in dipping balls into Sweet-and-Sour Sauce.', [I('cans (4 1/2 ounces each) shrimp, drained and finely chopped', 2, '', 'Pantry'), I('water chestnuts, finely chopped', 4, '', 'Pantry'), I('green onion, finely chopped', 1, '', 'Produce'), I('cornstarch', 1, 'tsp', 'Pantry'), I('sesame seed oil', 1, 'tsp', 'Pantry'), I('ground ginger', 0.25, 'tsp', 'Herbs & Spices'), I('Dash of white pepper', 1, '', 'Herbs & Spices'), I('egg white', 1, '', 'Dairy & Eggs'), I('Vegetable oil', 1, '', 'Pantry'), I('Sweet-and-Sour Sauce (page 8)', 1, '', 'Pantry')], ['Mix shrimp, water chestnuts, green onion, cornstarch, sesame seed oil, ginger and white pepper.', 'Beat egg white until foamy; stir into shrimp mixture.', 'Shape mixture into 1-inch balls.', 'Heat vegetable oil (1 1/2 to 1 3/4 inches) to 360°.', 'Fry 6 to 8 shrimp balls at a time until golden brown, turning 2 or 3 times, about 2 minutes.', 'Drain on paper towels.', 'Serve with Sweet-and-Sour Sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-046', 'Shrimp in Spicy Sauce', 'American', ["section-book-betty-intl"], 'seafood', 'fish', 45, 'On festive occasions, Indonesians serve sambal goreng udang with separate bowls of rice cooked in coconut milk and flavored with curry powder.', [I('vegetable oil', 0.25, 'cups', 'Pantry'), I('small raw shrimp, shelled and deveined', 1, 'lb', 'Meat & Seafood'), I('small onions, sliced', 2, '', 'Produce'), I('clove garlic, chopped', 1, '', 'Produce'), I('1/2 to 3/4 teaspoon crushed red pepper', 1, '', 'Herbs & Spices'), I('Coconut Milk', 1, 'cups', 'Other'), I('tomato, coarsely chopped', 1, '', 'Produce'), I('green pepper, thinly sliced into rings', 1, '', 'Produce'), I('packed brown sugar', 1, 'tbsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('Freshly ground pepper', 1, '', 'Herbs & Spices'), I('chopped fresh coconut', 1, 'cups', 'Produce'), I('hot water', 1, 'cups', 'Other')], ['Heat oil in 10-inch skillet until hot.', 'Cook and stir shrimp, onions, garlic and red pepper until shrimp starts to turn pink, 2 to 3 minutes.', 'Stir in remaining ingredients.', 'Simmer uncovered until shrimp is tender, about 5 minutes.', 'Serve in bowls.', 'Note: To open coconut, puncture eye of coconut with ice pick; drain liquid.', 'Bake coconut in 375° oven 12 to 15 minutes.', 'Remove from oven.', 'Tap shell with hammer to open.', 'Cut meat out of shell.', 'Pare brown skin from coconut meat.', 'Coconut Milk: Place 1 cup chopped fresh coconut and 1 cup hot water in blender container.', 'Cover and blend on high speed until coconut is finely chopped.', 'Strain through several layers of cheesecloth.', 'Refrigerate no longer than 48 hours.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-047', 'Spaghetti and Meatballs', 'American', ["section-book-betty-intl"], 'beef', 'green', 45, 'Spaghetti and Meatballs—nearly everyone\'s favorite "Italian" dish—is truly international fare.', [I('Meatballs', 1, '', 'Other'), I('medium onion, chopped', 1, '', 'Produce'), I('clove garlic, finely chopped', 1, '', 'Produce'), I('olive or vegetable oil', 1, 'tbsp', 'Pantry'), I('can (28 ounces) whole tomatoes', 1, '', 'Pantry'), I('can (6 ounces) tomato paste', 1, '', 'Pantry'), I('water', 0.25, 'cups', 'Other'), I('snipped parsley', 0.25, 'cups', 'Produce'), I('sugar', 1, 'tsp', 'Pantry'), I('salt', 1, 'tsp', 'Herbs & Spices'), I('dried basil leaves', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('package (16 ounces) spaghetti', 1, '', 'Pantry'), I('Grated Parmesan cheese', 1, '', 'Dairy & Eggs'), I('ground beef', 1.5, 'lb', 'Meat & Seafood'), I('dry bread crumbs', 0.75, 'cups', 'Bakery'), I('medium onion, finely chopped', 1, '', 'Produce'), I('milk', 0.5, 'cups', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('grated Parmesan cheese', 2, 'tbsp', 'Dairy & Eggs'), I('snipped parsley', 1, 'tbsp', 'Produce'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('dried oregano leaves', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('hot French bread (if desired)', 1, '', 'Bakery'), I('tossed green salad (if desired)', 1, '', 'Produce')], ['Prepare Meatballs.', 'Cook and stir onion and garlic in oil in Dutch oven over medium heat until onion is tender.', 'Add tomatoes (with liquid), tomato paste, water, parsley, sugar, salt, basil and pepper; break up tomatoes with fork.', 'Heat to boiling; reduce heat.', 'Cover and simmer, stirring occasionally, 30 minutes.', 'Add meatballs; cover and simmer 15 minutes.', 'Cook spaghetti as directed on package.', 'Drain; do not rinse.', 'Place spaghetti on large platter.', 'Top with meatballs and sauce.', 'Sprinkle with cheese.', 'Serve with hot French bread and tossed green salad if desired.', 'Meatballs: Mix all ingredients.', 'Shape mixture into 1 1/2-inch balls. (For easier shaping, dip hands into cold water from time to time.)', 'Place in ungreased jelly roll pan, 15 1/2 x 10 1/2 x 1 inch.', 'Cook uncovered in 350° oven until light brown, 15 to 20 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-048', 'Spanish Potato Omelet', 'American', ["section-book-betty-intl"], 'pork', 'skillet', 45, 'The Spanish word for omelet is tortilla—but in Spain, the tortilla bears no resemblance at all to the Mexican tortilla.', [I('6 or 7 slices bacon, cut into 1-inch pieces', 1, '', 'Meat & Seafood'), I('medium potato, cut into 1/2-inch cubes', 1, '', 'Produce'), I('medium onion, chopped', 1, '', 'Produce'), I('eggs', 6, '', 'Dairy & Eggs'), I('salt', 0.75, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices'), I('Parsley', 1, '', 'Produce')], ['Fry bacon in 10-inch skillet over medium heat until crisp.', 'Remove bacon and drain, reserving 4 tablespoons bacon fat in skillet.', 'Cook and stir potato and onion until potato is golden brown and tender, about 10 minutes.', 'Beat eggs with salt and pepper.', 'Stir bacon into potato mixture; add eggs.', 'Cover and cook over low heat until eggs are set and light brown on bottom, about 10 minutes.', 'Cut into wedges to serve; garnish with parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-049', 'Stuffed Green Peppers and Tomatoes', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'Stuffed vegetables are popular throughout the Middle East and the Mediterranean, and may be served hot or cold.', [I('medium green peppers', 4, '', 'Produce'), I('large firm tomatoes', 4, '', 'Produce'), I('medium onion, chopped', 1, '', 'Produce'), I('unsalted sunflower seeds (shelled)', 2, 'tbsp', 'Pantry'), I('vegetable oil', 2, 'tbsp', 'Pantry'), I('water', 1.3333333333333333, 'cups', 'Other'), I('uncooked regular rice', 0.6666666666666666, 'cups', 'Pantry'), I('raisins', 0.25, 'cups', 'Pantry'), I('snipped parsley', 0.25, 'cups', 'Produce'), I('finely snipped fresh mint or 1 teaspoon dried mint leaves', 1, 'tbsp', 'Produce'), I('salt', 2, 'tsp', 'Herbs & Spices'), I('ground cinnamon', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('water', 1, 'cups', 'Other'), I('tomato paste', 0.25, 'cups', 'Pantry')], ['Cut thin slice from stem end of each green pepper and tomato; reserve.', 'Remove seeds and membranes from green peppers; rinse peppers.', 'Cook green peppers in enough boiling water to cover 5 minutes; drain.', 'Cut thin slice from bottom of each tomato if necessary to prevent tipping.', 'Remove pulp from tomatoes, leaving a 1/4-inch wall.', 'Chop pulp; reserve.', 'Cook onion and sunflower seeds in oil in 10-inch skillet over medium heat, stirring frequently, 5 minutes.', 'Stir in reserved pulp, 1 1/3 cups water, the rice, raisins, parsley, mint, salt, cinnamon and pepper.', 'Heat to boiling; reduce heat.', 'Cover and simmer 15 minutes.', 'Uncover and simmer 3 to 5 minutes to reduce liquid if necessary.', 'Stuff each tomato and green pepper with rice mixture, filling each about 3/4 full.', 'Place stem tops on each.', 'Arrange vegetables in ungreased oblong baking dish, 13 1/2 x 9 x 2 inches.', 'Mix 1 cup water and the tomato paste; pour around vegetables.', 'Cover tightly with aluminum foil.', 'Cook in 350° oven until vegetables are tender, about 45 minutes.', 'Serve hot or cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-050', 'Stuffed Rolled Fish Fillets', 'American', ["section-book-betty-intl"], 'fish', 'dessert', 45, 'These Latin American fish rolls are appropriately complemented with Sweet Potatoes with Apples (page 243) or Zucchini-Avocado Salad (page 209).', [I('fish fillets', 2, 'lb', 'Meat & Seafood'), I('medium onions, chopped', 2, '', 'Produce'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('soft bread crumbs', 2, 'cups', 'Bakery'), I('snipped parsley', 0.5, 'cups', 'Produce'), I('salt', 2, 'tsp', 'Herbs & Spices'), I('ground nutmeg', 0.5, 'tsp', 'Herbs & Spices'), I('eggs, slightly beaten', 2, '', 'Dairy & Eggs'), I('margarine or butter, melted', 2, 'tbsp', 'Dairy & Eggs'), I('lemon juice', 1, 'tbsp', 'Produce'), I('Paprika', 1, '', 'Herbs & Spices'), I('Snipped parsley', 1, '', 'Produce')], ['If fish fillets are large, cut into serving pieces.', 'Cook and stir onions in 1/4 cup margarine until tender.', 'Stir in bread crumbs, 1/2 cup parsley, the salt, nutmeg and eggs.', 'Spread mixture evenly over fish fillets.', 'Roll up fish fillets; fasten with wooden picks.', 'Place seam sides down in ungreased oblong baking dish, 10 x 6 x 1 1/2 inches, or square baking dish, 8 x 8 x 2 inches.', 'Mix melted margarine and lemon juice; drizzle over fish.', 'Sprinkle with paprika.', 'Cook uncovered in 350° oven until fish flakes easily with fork, about 25 minutes.', 'Garnish with parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-051', 'Sugar-Browned Potatoes', 'American', ["section-book-betty-intl"], 'veg', 'skillet', 45, 'The Danes like to serve this luscious potato dish with their much-loved pork.', [I('new potatoes', 2, 'lb', 'Produce'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('sugar', 0.25, 'cups', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('water', 3, 'tbsp', 'Other')], ['Heat 1 inch salted water (1 teaspoon salt to 1 cup water) to boiling.', 'Add potatoes.', 'Heat to boiling; reduce heat.', 'Cover and cook until tender, 20 to 25 minutes; drain.', 'Cook and stir margarine, sugar and salt in 10-inch skillet over medium heat until mixture starts to turn golden brown.', 'Remove from heat; cool slightly.', 'Stir in water until blended.', 'Add potatoes.', 'Cook over low heat, turning potatoes to coat with sugar mixture.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-052', 'Swedish Meatballs', 'American', ["section-book-betty-intl"], 'beef', 'bowl', 45, 'The creative Swedes have many ways with meatballs—but cream is nearly always included, either in the meatballs or in an accompanying sauce.', [I('ground beef', 1, 'lb', 'Meat & Seafood'), I('ground pork', 0.5, 'lb', 'Meat & Seafood'), I('dry bread crumbs', 0.75, 'cups', 'Bakery'), I('milk', 0.25, 'cups', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('small onion, finely chopped', 1, '', 'Produce'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('ground nutmeg', 0.25, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('flour', 3, 'tbsp', 'Pantry'), I('water', 0.75, 'cups', 'Other'), I('half-and-half', 1, 'cups', 'Dairy & Eggs'), I('instant beef bouillon', 1, 'tsp', 'Pantry'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('Snipped parsley', 1, '', 'Produce')], ['Mix beef, pork, bread crumbs, milk, egg, onion, 1 1/2 teaspoons salt, the nutmeg and pepper.', 'Shape mixture into 1-inch balls. (For easy shaping, dip hands into cold water from time to time.)', 'Place meatballs on ungreased jelly roll pan, 15 1/2 x 10 1/2 x 1 inch, or 2 oblong pans, 13 x 9 x 2 inches.', 'Cook uncovered in 350° oven until light brown, about 20 minutes.', 'Remove meatballs to serving dish; keep warm.', 'Place 3 tablespoons pan drippings in saucepan; stir in flour.', 'Cook over low heat, stirring constantly, until mixture is smooth and bubbly.', 'Remove from heat.', 'Stir in water, half-and-half, bouillon and 1/2 teaspoon salt.', 'Heat to boiling, stirring constantly.', 'Boil and stir 1 minute.', 'Pour gravy over meatballs; sprinkle with parsley.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-053', 'Swedish Rye Bread', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'Americans have concocted many versions of limpa.', [I('packages active dry yeast', 2, '', 'Pantry'), I('warm water (105 to 115°)', 1.5, 'cups', 'Pantry'), I('packed brown sugar', 0.3333333333333333, 'cups', 'Pantry'), I('molasses', 0.3333333333333333, 'cups', 'Pantry'), I('salt', 1, 'tbsp', 'Herbs & Spices'), I('anise seed or fennel seed, crushed', 1, 'tbsp', 'Pantry'), I('finely shredded orange peel', 1, 'tbsp', 'Produce'), I('vegetable oil', 2, 'tbsp', 'Pantry'), I('medium rye flour', 2.5, 'cups', 'Pantry'), I('2 1/4 to 2 3/4 cups all-purpose or unbleached flour', 1, '', 'Pantry'), I('margarine or butter (if desired)', 1, '', 'Dairy & Eggs')], ['Dissolve yeast in warm water in large bowl.', 'Stir in brown sugar, molasses, salt, anise seed, orange peel, oil and rye flour.', 'Beat until smooth.', 'Stir in enough all-purpose flour to make a soft dough.', 'Turn dough onto lightly floured surface.', 'Cover; let rest 10 to 15 minutes.', 'Knead until smooth and elastic, about 5 minutes.', 'Place in greased bowl; turn greased side up.', 'Cover; let rise in warm place until double, about 1 hour. (Dough is ready if indentation remains when touched.)', 'Punch down dough; divide into halves.', 'Shape each half into a round, slightly flat loaf.', 'Place loaves in opposite corners of greased cookie sheet.', 'Cover; let rise until double, about 1 hour.', 'Heat oven to 375°.', 'Bake until loaves sound hollow when tapped, 40 to 50 minutes.', 'Brush with margarine or butter if desired.', 'Cool on wire racks.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-054', 'Swiss Fried Potatoes', 'American', ["section-book-betty-intl"], 'veg', 'dessert', 45, 'Switzerland\'s much-praised fried potatoes are often served for breakfast (like our hash browns), accompanied by porridge or eggs, bacon and coffee liberally laced with warm milk.', [I('medium potatoes (about 1 1/2 pounds)', 4, '', 'Produce'), I('margarine or butter', 0.25, 'cups', 'Dairy & Eggs'), I('small onion, chopped', 1, '', 'Produce'), I('diced Gruyére or Swiss cheese', 0.5, 'cups', 'Dairy & Eggs'), I('salt', 0.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.25, 'tsp', 'Herbs & Spices'), I('water', 2, 'tbsp', 'Other')], ['Heat 1 inch salted water (1/2 teaspoon salt to 1 cup water) to boiling.', 'Add potatoes.', 'Heat to boiling; reduce heat.', 'Cover and cook until tender, 30 to 35 minutes.', 'Peel and shred potatoes or cut into 1/4-inch strips.', 'Heat margarine in 10-inch skillet until melted.', 'Add potatoes, onion and cheese.', 'Sprinkle with salt and pepper.', 'Cook uncovered over medium heat, turning frequently, until potatoes start to brown, about 10 minutes. (Add 1 to 2 tablespoons margarine to prevent sticking if necessary.)', 'Press potatoes with spatula to form flat cake; sprinkle with water.', 'Cover and cook over low heat, without stirring, until bottom is golden brown and crusty, about 10 minutes.', 'Place inverted platter over skillet; invert potatoes onto platter.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-055', 'Vegetable Soup', 'American', ["section-book-betty-intl"], 'veg', 'soup', 45, 'Crisp fresh vegetables add color and delicious flavor to kesakeitto—which requires less than twenty minutes cooking time!', [I('water', 2, 'cups', 'Other'), I('small carrots, sliced', 2, '', 'Produce'), I('medium potato, cubed', 1, '', 'Produce'), I('fresh or frozen green peas', 0.75, 'cups', 'Produce'), I('cut fresh or frozen green beans', 1, 'cups', 'Produce'), I('small cauliflower, separated into flowerets', 0.25, '', 'Produce'), I('spinach, cut up (about 2 cups)', 2, 'oz', 'Produce'), I('milk', 2, 'cups', 'Dairy & Eggs'), I('flour', 2, 'tbsp', 'Pantry'), I('whipping cream', 0.25, 'cups', 'Dairy & Eggs'), I('salt', 1.5, 'tsp', 'Herbs & Spices'), I('pepper', 0.125, 'tsp', 'Herbs & Spices'), I('Snipped dillweed or parsley (optional)', 1, '', 'Produce')], ['Heat water, carrots, potato, peas, beans and cauliflower to boiling in 3-quart saucepan; reduce heat.', 'Cover and simmer until vegetables are almost tender, 10 to 15 minutes.', 'Add spinach; cook uncovered about 1 minute.', 'Mix 1/4 cup of the milk and the flour; stir gradually into vegetable mixture.', 'Boil and stir 1 minute.', 'Stir in remaining milk, the whipping cream, salt and pepper.', 'Heat just until hot.', 'Garnish each serving with dill.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-056', 'Wonton Soup', 'American', ["section-book-betty-intl"], 'pork', 'soup', 45, 'This is our homemade version of the popular Chinese restaurant soup.', [I('ground pork', 0.5, 'lb', 'Meat & Seafood'), I('green onion (with top), chopped', 1, '', 'Produce'), I('soy sauce', 2, 'tsp', 'Pantry'), I('cornstarch', 0.5, 'tsp', 'Pantry'), I('ground ginger', 0.25, 'tsp', 'Herbs & Spices'), I('salt', 0.25, 'tsp', 'Herbs & Spices'), I('wonton skins', 24, '', 'Pantry'), I('water', 5, 'cups', 'Other'), I('cans (10 3/4 ounces each) condensed chicken broth', 3, '', 'Pantry'), I('soup cans water', 3, '', 'Pantry'), I('soy sauce', 1, 'tbsp', 'Pantry'), I('spinach, torn into small pieces, or 1 cup watercress', 1, 'cups', 'Produce')], ['Cook and stir pork and green onion until pork is brown; drain.', 'Mix pork, green onion, 2 teaspoons soy sauce, the cornstarch, ginger and salt.', 'Place 1 teaspoon filling on center of each wonton skin.', 'Moisten edges with water.', 'Fold each skin in half to form triangle; press edges to seal.', 'Pull bottom corners of triangle down and overlap slightly.', 'Moisten one corner with water; pinch to seal. (Wontons can be covered and refrigerated no longer than 24 hours.)', 'Heat 5 cups water to boiling in Dutch oven; add wontons.', 'Heat to boiling; reduce heat.', 'Simmer uncovered 2 minutes. (Wontons will break apart if overcooked.)', 'Drain.', 'Heat chicken broth, 3 cans water and 1 tablespoon soy sauce to boiling in 3-quart saucepan; add spinach.', 'Heat just to boiling.', 'Place 3 wontons and 1 cup hot broth in each soup bowl.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('bint-057', 'Yogurt Salad', 'American', ["section-book-betty-intl"], 'veg', 'green', 45, 'During the hot summer months, the Turks often lunch on a light, nutritious salad, rounding out the meal with cheese and bread.', [I('unflavored yogurt', 1, 'cups', 'Dairy & Eggs'), I('finely snipped fresh mint or 1/2 teaspoon dried mint flakes', 2, 'tbsp', 'Produce'), I('lemon juice', 1, 'tbsp', 'Produce'), I('clove garlic, finely chopped', 1, '', 'Produce'), I('Dash of white pepper', 1, '', 'Herbs & Spices'), I('medium cucumber, thinly sliced', 1, '', 'Produce')], ['Mix all ingredients except cucumber; cover and refrigerate.', 'Just before serving, stir in cucumber.', 'Place in serving dish; garnish with additional mint if desired.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
];

